    {
        Views myView = _context.Views.SingleOrDefault(a => a.Id.ToString().ToLower() == ViewId.ToLower());
        if (myView == null)
        {
            myView = _context.Views.SingleOrDefault(a => a.DisplayName == ViewId);
        }
        //select the view by view Id

        if (myView != null)
        {
            List<DataSourceFields> fields = _context.DataSourceFields.Where(a => a.DataSourceId == myView.DataSourceId).ToList();
            if (fields.Count > 0)
            {
                string select = "", where = "", groupby = "", from = "",having="";
                List<Entities> currEntities = new List<Entities>();
                List<SqlParameter> parameters = new List<SqlParameter>();

                for (var i = 0; i < fields.Count; i++)
                {
                    DataSourceFields field = fields[i];
                    Fields myfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == field.FieldId);
                    Entities myentity = currEntities.FirstOrDefault(a => a.Id.ToString().ToLower() == field.EntityId.ToLower());
                    if (myentity == null)
                    {
                        myentity = _context.Entities.FirstOrDefault(a => a.Id.ToString() == field.EntityId);
                        currEntities.Add(myentity);
                    }
                    if (myfield != null && myentity != null)
                        AddToSelect(ref select, ref where, ref groupby, ref having, parameters, field, myfield, myentity);

                }

                if (currEntities.Count > 1)
                {
                    from = CreateJoinString(fields, from, currEntities);
                }
                else
                {
                    Entities myentity = currEntities[0];
                    from += "[dbo].[" + myentity.SysName + "] as [" + myentity.DisplayName + "] ";
                }
                if (select != "")
                {
                    select = "SELECT " + select;
                }
                if (from != "")
                {
                    from = " FROM " + from;
                }
                if (where != "")
                {
                    where = " WHERE " + where;
                }
                if (groupby != "")
                {
                    groupby = " GROUP BY " + groupby;
                    if(having!="")
                    {
                        having = " HAVING " + having;
                    }
                }
                if (select != "" && from != "")
                {
                    string sql = select + from + where + groupby + having;
                    return database.GetData(sql, parameters.ToArray());
                }
            }
        }

    }
    return new List<dynamic>();
